def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_re = re.compile(r"\d+|[A-Z]+\d*|<>|<=|>=|[()+*/,:<>=-]")
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def parse_integer(text):
        negative = text.startswith("-")
        if negative:
            text = text[1:]
        value = 0
        for i in range(0, len(text), 9):
            part = text[i:i + 9]
            value = value * (10 ** len(part)) + int(part)
        return -value if negative else value

    def parse(text):
        tokens = token_re.findall(text)
        nodes = []
        operators = []
        comma_counts = []
        expecting_operand = True

        def apply_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append((op, left, right))

        i = 0
        while i < len(tokens):
            token = tokens[i]

            if token.isdigit():
                nodes.append(("number", parse_integer(token)))
                expecting_operand = False
            elif token[0].isalpha():
                if i + 1 < len(tokens) and tokens[i + 1] == "(":
                    operators.append(("function", token))
                    expecting_operand = True
                else:
                    nodes.append(("cell", token))
                    expecting_operand = False
            elif token == "(":
                operators.append(token)
                comma_counts.append(0)
                expecting_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    apply_operator()
                comma_counts[-1] += 1
                expecting_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    apply_operator()
                operators.pop()
                count = comma_counts.pop() + 1
                if operators and isinstance(operators[-1], tuple):
                    function = operators.pop()[1]
                    args = nodes[-count:]
                    del nodes[-count:]
                    nodes.append(("function", function, args))
                expecting_operand = False
            else:
                op = "neg" if token == "-" and expecting_operand else token
                while operators and isinstance(operators[-1], str):
                    top = operators[-1]
                    if top == "(":
                        break
                    if precedence[top] > precedence[op] or (
                        precedence[top] == precedence[op] and op != "neg"
                    ):
                        apply_operator()
                    else:
                        break
                operators.append(op)
                expecting_operand = True
            i += 1

        while operators:
            apply_operator()
        return nodes[0]

    def argument_nodes(args):
        for arg in args:
            if arg[0] != ":":
                yield arg
                continue

            first = arg[1][1]
            second = arg[2][1]
            col1, col2 = sorted((ord(first[0]), ord(second[0])))
            row1, row2 = sorted((int(first[1:]), int(second[1:])))
            for row in range(row1, row2 + 1):
                for col in range(col1, col2 + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("cell", name)

    values = {}
    active = set()

    def evaluate(start):
        tasks = [("cell", start)]
        results = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in values:
                    results.append(values[name])
                elif name not in cells:
                    results.append(0)
                elif name in active:
                    results.append("#CYCLE!")
                else:
                    active.add(name)
                    content = cells[name]
                    if content.startswith("="):
                        node = parse(content[1:])
                        tasks.append(("finish_cell", name))
                        tasks.append(("eval", node))
                    else:
                        value = parse_integer(content)
                        values[name] = value
                        active.remove(name)
                        results.append(value)

            elif kind == "finish_cell":
                name = task[1]
                values[name] = results[-1]
                active.remove(name)

            elif kind == "eval":
                node = task[1]
                op = node[0]
                if op == "number":
                    results.append(node[1])
                elif op == "cell":
                    tasks.append(("cell", node[1]))
                elif op == "neg":
                    tasks.append(("neg",))
                    tasks.append(("eval", node[1]))
                elif op == "function":
                    name, args = node[1], node[2]
                    if name == "IF":
                        tasks.append(("if", args[1], args[2]))
                        tasks.append(("eval", args[0]))
                    else:
                        tasks.append(("aggregate", name, iter(argument_nodes(args)), None))
                else:
                    tasks.append(("binary_left", op, node[2]))
                    tasks.append(("eval", node[1]))

            elif kind == "neg":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                op, right = task[1], task[2]
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("binary_right", op, left))
                    tasks.append(("eval", right))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(left == right)
                elif op == "<>":
                    results.append(left != right)
                elif op == "<":
                    results.append(left < right)
                elif op == "<=":
                    results.append(left <= right)
                elif op == ">":
                    results.append(left > right)
                elif op == ">=":
                    results.append(left >= right)

            elif kind == "if":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate":
                name, iterator, aggregate = task[1], task[2], task[3]
                try:
                    next_node = next(iterator)
                except StopIteration:
                    results.append(0 if aggregate is None else aggregate)
                else:
                    tasks.append(("aggregate_value", name, iterator, aggregate))
                    tasks.append(("eval", next_node))

            elif kind == "aggregate_value":
                name, iterator, aggregate = task[1], task[2], task[3]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if aggregate is None:
                        aggregate = value
                    elif name == "SUM":
                        aggregate += value
                    elif name == "MIN":
                        aggregate = min(aggregate, value)
                    else:
                        aggregate = max(aggregate, value)
                    tasks.append(("aggregate", name, iterator, aggregate))

        return results.pop()

    return {name: evaluate(name) for name in cells}
